package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.PhoneNumberVO;

class PhoneNumberValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of phone number of user profile")
  void test_phone_number_value_holder_assign_plain_value() {
    Object holder = new Object();
    PhoneNumberValueHolder<Object> value = new PhoneNumberValueHolder<>(holder);
    Assertions.assertSame(holder, value.phoneNumber("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPhoneNumberValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getPhoneNumber().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.phoneNumberNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPhoneNumberValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPhoneNumber().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of phone number of user profile")
  void test_phone_number_value_holder_assign_value_object() {
    Object holder = new Object();
    PhoneNumberValueHolder<Object> value = new PhoneNumberValueHolder<>(holder);
    PhoneNumberVO vo = PhoneNumberVO.from("one");
    Assertions.assertFalse(value.getPhoneNumberValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.phoneNumber(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPhoneNumberValue().orElseThrow());
    Assertions.assertSame(holder, value.phoneNumber(Optional.empty()));
    Assertions.assertFalse(value.getPhoneNumberValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.phoneNumber(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPhoneNumberValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of phone number of user profile against the original")
  void test_phone_number_value_holder_read() {
    Object holder = new Object();
    PhoneNumberValueHolder<Object> value = new PhoneNumberValueHolder<>(holder);
    PhoneNumberVO vo = PhoneNumberVO.from("one");
    PhoneNumberVO other = PhoneNumberVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getPhoneNumberValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPhoneNumber(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPhoneNumber(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.phoneNumber(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPhoneNumber(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPhoneNumber(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of phone number of user profile")
  void test_phone_number_value_holder_unset() {
    Object holder = new Object();
    PhoneNumberValueHolder<Object> value = new PhoneNumberValueHolder<>(holder);
    PhoneNumberVO vo = PhoneNumberVO.from("one");
    value.phoneNumber(vo);
    Assertions.assertSame(holder, value.unsetPhoneNumberIfMatches("phoneNumber_other"));
    Assertions.assertTrue(value.getPhoneNumberValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPhoneNumberIfMatches("phoneNumber"));
    Assertions.assertFalse(value.getPhoneNumberValue().isPresent(),
        "The field name must clear the value");
    value.phoneNumber(vo);
    Assertions.assertSame(holder, value.unsetPhoneNumber());
    Assertions.assertFalse(value.getPhoneNumberValue().isPresent(), "Unset must clear the value");
  }
}
